import React, { useState, useEffect } from 'react';

const PortfolioNotice = () => {
    const [showPopup, setShowPopup] = useState(false);

    useEffect(() => {
        const timer = setTimeout(() => {
            setShowPopup(true);
        }, 3000); // Show popup after 3 seconds

        return () => clearTimeout(timer); // Clear timeout if component unmounts
    }, []);

    return (
        <>
            <div className="portfolio-notice" onClick={() => setShowPopup(true)}>
                🎉 Check out my new portfolio!
            </div>
            {showPopup && (
                <div className="portfolio-popup">
                    <div className="popup-content">
                        <h3>New Portfolio Available!</h3>
                        <p>I've created a new portfolio with updated projects and skills.</p>
                        <div className="popup-buttons">
                            <a href="https://devesh-mehta.vercel.app?utm_source=old_portfolio" target="_blank" rel="noopener noreferrer" className="visit-btn">Visit Now</a>
                            <button onClick={() => setShowPopup(false)} className="close-btn">Close</button>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
};

export default PortfolioNotice;
